def compute(vars):
    value_2017 = vars["v1"]
    value_2018 = vars["v2"]
    higher_year = "2018" if value_2018 > value_2017 else "2017" if value_2017 > value_2018 else "tie"

    return {
        "value": higher_year,
        "trace": {
            "value_2017": value_2017,
            "value_2018": value_2018,
            "comparison": "2018 > 2017" if value_2018 > value_2017 else "2017 > 2018" if value_2017 > value_2018 else "equal",
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": None
            }
        }
    }
